  const rail=make('div','awards-actions');for(const id of['results-help','next-round','return-lobby'])rail.append(document.getElementById(id)!);document.getElementById('results')!.append(rail);
  document.addEventListener('visibilitychange',()=>{if(document.hidden){this.settle();this.clearConfetti();}});this.motion.addEventListener('change',()=>{if(this.motion.matches){this.settle();this.clearConfetti();}});
 }
 private portrait(f:ResultsFrog){const portrait=make('div','awards-frog');portrait.innerHTML=appearancePreview(f.appearance);return portrait;}
 private score(f:ResultsFrog,animate:boolean){const element=make('strong','awards-score',scoreText(animate?f.previous:f.total));element.dataset.total=String(f.total);element.setAttribute('aria-label',`${scoreText(f.total)} points`);if(animate)this.targets.push({element,from:f.previous,to:f.total});return element;}
 private identity(f:ResultsFrog){const label=make('div','awards-identity'),name=make('strong','awards-name',f.name);name.title=f.name;label.append(name);if(f.local)label.append(make('small','awards-you','YOU'));if(f.status)label.append(make('small','awards-status',f.status));return label;}
 update(view:OutbreakView|undefined,lobby:LobbyState|undefined,localId:string,voting=false){
  view=finalResultsView(view);const inMatch=lobby?.phase==='game';const scope=inMatch?`${lobby.code}:${(lobby.roster??lobby.players).map(p=>p.id).join('|')}`:'';
  if(scope!==this.scope){this.scope=scope;this.seen.clear();this.signature='';}
  const visible=!!view&&inMatch&&!voting&&['round-results','match-results'].includes(view.phase);
  document.body.classList.toggle('results-celebration',visible);this.root.hidden=!visible;
  if(!visible){this.settle();this.clearConfetti();this.signature='';return;}
  const model=resultsModel(view!,lobby!,localId);this.root.dataset.final=String(model.final);this.root.dataset.wideTie=String(model.groups.some(g=>g.frogs.length>3));
  document.getElementById('results-title')!.textContent=this.root.classList.contains('reveal-pending')?'THE POND HOLDS ITS BREATH…':this.root.classList.contains('podium-revealing')?'FINAL STANDINGS':model.final?(view!.matchWinners.length>1?'FROG-OUT CHAMPIONS!':'FROG-OUT CHAMPION!'):'ROUND COMPLETE!';
  const scoreKey=JSON.stringify([scope,view!.mode,view!.phase,view!.round,model.frogs.map(f=>[f.slot,f.total,f.delta])]);
  const signature=JSON.stringify([scoreKey,model.frogs]);if(signature===this.signature)return;
  this.settle();this.clearConfetti();this.signature=signature;const animate=!this.seen.has(scoreKey)&&!this.motion.matches;const firstVisit=!this.seen.has(scoreKey);this.seen.add(scoreKey);this.targets=[];
  this.stage.replaceChildren();
  const podium=make('div','frog-podium');podium.setAttribute('aria-label',model.final?'Final match podium':'Match standings after this round');podium.dataset.tied=String(model.tiedPodium);podium.dataset.groups=String(model.groups.length);
  for(const group of model.groups){const tier=make('div','podium-tier');tier.dataset.rank=String(group.rank);tier.dataset.count=String(group.frogs.length);const frogs=make('div','podium-frogs');for(const f of group.frogs){const frog=make('div',`podium-contender${f.champion?' champion':''}`);frog.dataset.player=f.id;frog.dataset.slot=String(f.slot);frog.append(this.portrait(f),this.identity(f),this.score(f,animate&&!model.final));frogs.append(frog);}const base=make('div','podium-base');base.append(make('strong','podium-rank',rankText(group.rank,group.frogs.length>1)));tier.append(frogs,base);podium.append(tier);}
  const standings=make('div','frog-standings'),heading=make('h3','awards-board-heading',model.final?'EVERY FROG. EVERY POINT.':'MATCH TOTALS · GAINS THIS ROUND');const board=make('div','awards-board');board.setAttribute('role','list');board.tabIndex=0;board.setAttribute('aria-label','All player standings; scroll to see more frogs when needed');heading.append(make('small','standings-scroll-hint',' · SCROLL ↕')); 
  for(const f of model.frogs){const card=make('article',`awards-player${f.delta>0?' gained':''}${f.champion?' champion':''}`);card.setAttribute('role','listitem');card.dataset.player=f.id;card.dataset.slot=String(f.slot);card.dataset.local=String(f.local);card.style.setProperty('--player-color','#'+skinFor(f.appearance).color.toString(16).padStart(6,'0'));const rank=make('span','awards-rank',rankText(f.rank,f.tied));const info=make('div','awards-player-info');info.append(this.identity(f));const numbers=make('div','awards-numbers');numbers.append(this.score(f,animate&&!model.final));if(!model.final){const gain=make('span','awards-gain',`+${scoreText(f.delta)}`);gain.setAttribute('aria-label',`${scoreText(f.delta)} points gained this round`);gain.append(make('span','gain-caption',' this round'));numbers.append(gain);}info.append(numbers);const movement=make('small','awards-movement',movementText(f));movement.dataset.direction=f.firstStandings?'first':f.movement>0?'up':f.movement<0?'down':'same';movement.title=f.firstStandings?'First cumulative ranking':`${rankText(f.previousRank)} → ${rankText(f.rank)}`;movement.setAttribute('aria-label',`${movementText(f)}; ${movement.title}`);if(!model.final)info.append(movement);if(!model.final&&f.roundWinner)info.append(make('small','awards-round-winner','Round winner'));card.append(rank,this.portrait(f),info);board.append(card);}
  standings.append(heading,board);this.stage.append(podium,standings);this.root.dataset.count=String(model.frogs.length);
  this.root.setAttribute('aria-label',model.final?'Final standings':'Round standings');
  if(model.final&&firstVisit&&!this.motion.matches){this.root.classList.add('reveal-pending');this.stage.setAttribute('aria-hidden','true');const reveal=make('div','champion-reveal','THE POND HOLDS ITS BREATH…');reveal.setAttribute('role','status');reveal.append(make('small','','A champion is about to leap into the spotlight!'));this.root.append(reveal);document.getElementById('results-title')!.textContent='THE POND HOLDS ITS BREATH…';const order=podiumRevealOrder(model.frogs);this.root.classList.add('podium-revealing');document.getElementById('score-breakdown')!.hidden=true;for(const node of Array.from(this.stage.querySelectorAll<HTMLElement>('.podium-contender'))){node.classList.add('podium-waiting');node.setAttribute('aria-hidden','true');}this.revealTimer=setTimeout(()=>{this.finishCurtain();document.getElementById('results-title')!.textContent='FINAL STANDINGS';order.forEach((slot,i)=>this.podiumTimers.push(setTimeout(()=>{const node=this.stage.querySelector<HTMLElement>(`.podium-contender[data-slot="${slot}"]`);node?.classList.remove('podium-waiting');node?.classList.add('podium-entering');node?.removeAttribute('aria-hidden');if(i===order.length-1){this.finishReveal();this.confetti();this.celebrate();}},i*PODIUM_STEP_MS)));},FINAL_REVEAL_MS);}else if(animate&&!model.final)this.animate();else{this.root.classList.add('scores-settled');if(model.final&&firstVisit)this.celebrate();}
 }
 private animate(){this.root.classList.remove('scores-settled');const start=performance.now();const frame=(now:number)=>{const elapsed=now-start;for(const t of this.targets)t.element.textContent=scoreText(countedScore(t.from,t.to,elapsed));if(elapsed<SCORE_COUNT_MS)this.frame=requestAnimationFrame(frame);else this.settle();};this.frame=requestAnimationFrame(frame);}
 private finishCurtain(){clearTimeout(this.revealTimer);this.revealTimer=undefined;this.root.classList.remove('reveal-pending');this.stage.removeAttribute('aria-hidden');this.root.querySelector('.champion-reveal')?.remove();}
 private finishReveal(){const pending=this.root.classList.contains('reveal-pending')||this.root.classList.contains('podium-revealing');this.finishCurtain();for(const timer of this.podiumTimers)clearTimeout(timer);this.podiumTimers=[];this.root.classList.remove('podium-revealing');for(const node of Array.from(this.stage.querySelectorAll('.podium-contender'))){node.classList.remove('podium-waiting');node.removeAttribute('aria-hidden');}const details=document.getElementById('score-breakdown');if(details)details.hidden=false;if(pending){document.getElementById('results-title')!.textContent=this.stage.querySelectorAll('.podium-contender.champion').length>1?'FROG-OUT CHAMPIONS!':'FROG-OUT CHAMPION!';}}
 private settle(){this.finishReveal();if(this.frame)cancelAnimationFrame(this.frame);this.frame=0;for(const t of this.targets)t.element.textContent=scoreText(t.to);this.root.classList.add('scores-settled');}
 private confetti(){const burst=make('div','awards-confetti');burst.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const piece=make('i','confetti-piece');piece.style.setProperty('--i',String(i));piece.style.left=`${(i*37)%100}%`;piece.style.background=['#ffdf83','#a9e7ad','#93dcec','#f4a5be','#c9b3f5'][i%5];burst.append(piece);}this.root.prepend(burst);this.confettiTimer=setTimeout(()=>this.clearConfetti(),2600);}
 private clearConfetti(){clearTimeout(this.confettiTimer);this.confettiTimer=undefined;this.root.querySelector('.awards-confetti')?.remove();}
}

