test('Every face attaches at actual contact, never platform center; stationary grip and screen-direction tangent crawl',()=>{for(const normal of[Vec2(0,-1),Vec2(0,1),Vec2(-1,0),Vec2(1,0)])for(const angle of[0,.35]){const s=fresh(),{b,f,out}=face(s,normal,angle);assert.ok(s.stickyFrogs.support(f));const stored=capture(s).stickyFrogs!.attachments[0]!;assert.ok(Math.hypot(stored.point.x,stored.point.y)>.25);const start=f.body.getPosition().clone();for(let i=0;i<120;i++)s.step();assert.ok(s.stickyFrogs.support(f),'lost idle face '+JSON.stringify(normal));assert.ok(Vec2.distance(start,f.body.getPosition())<.15);const tangent=Vec2(-out.y,out.x);s.setInput(0,{x:tangent.x,y:tangent.y,held:false});for(let i=0;i<12;i++)s.step();const v=f.body.getLinearVelocity();assert.ok(Vec2.dot(v,tangent)>2);assert.ok(s.stickyFrogs.support(f)?.body===b);}});
test('Tap and full charged jumps launch along current face normal, retain tangent and delay reattachment',()=>{for(const normal of[Vec2(0,-1),Vec2(0,1),Vec2(-1,0),Vec2(1,0)])for(const charged of[false,true]){const s=fresh(),{f,out}=face(s,normal,.2);s.setInput(0,{x:0,y:0,held:true});for(let i=0;i<(charged?65:1);i++)s.step();assert.equal(f.jumpPending,true);if(charged)assert.equal(f.charge,defaults.chargeSeconds);s.setInput(0,{x:0,y:0,held:false});s.step();assert.ok(Vec2.dot(f.body.getLinearVelocity(),out)>(charged?16:8));assert.equal(s.stickyFrogs.support(f),undefined);const state=capture(s).stickyFrogs!;assert.ok(state.cooldowns[0]>=s.tick+10);}});
test('Floor to wall inner corner transitions are physical and deterministic; outer edge releases rather than snapping',()=>{const s=fresh(),{f}=face(s);const wall=s.world.createBody(Vec2(11.9,8));wall.createFixture(Box(.2,1.8));s.setInput(0,{x:1,y:-1,held:false});for(let i=0;i<45;i++)s.step();assert.ok(f.body.getPosition().x<12.5);assert.ok(f.body.getPosition().y<8.5);assert.ok(s.stickyFrogs.normal(f)!.x<-.9);const q=fresh(),{f:g}=face(q);q.setInput(0,{x:1,y:0,held:false});for(let i=0;i<65;i++)q.step();assert.ok(g.body.getPosition().x>12);assert.equal(q.stickyFrogs.support(g),undefined);});
