test('Reconnect snapshot retains local surface identity, cooldown and exact state; expiry/round reset/rematch clear adhesion',()=>{const s=fresh(['sticky_frogs','tilt_a_frog']);const f=s.frogs[0];f.body.setTransform(Vec2(.5+s.tuning.frogRadius-.01,8),0);s.world.step(0);s.step();assert.ok(s.stickyFrogs.support(f));const state=capture(s),clone=fresh(['sticky_frogs','tilt_a_frog']);restore(clone,state);assert.deepEqual(capture(clone),state);for(let i=0;i<30;i++){s.step();clone.step();}assert.ok(Vec2.distance(s.frogs[0].body.getPosition(),clone.frogs[0].body.getPosition())<.00001);s.reset();assert.ok(capture(s).stickyFrogs!.attachments.every(a=>a===null));applyChaos(s,[]);assert.equal(capture(s).stickyFrogs,undefined);});
