test('Official twentieth modifier replaces Flappy; pair eligibility, KEEP renewal, duplicates and baseline remain correct',()=>{assert.equal(MODIFIERS.length,20);assert.ok(!MODIFIERS.some(m=>(m.id as string)==='flappy_frogs'));for(const extra of['gravity_flip','moon_frogs','tilt_a_frog','crumble_time','butterfeet','pogo_panic','mega_tongues','super_suckers','tiny_trouble','mega_frogs','windy_weather']as ModifierId[]){assert.equal(validModifiers(['sticky_frogs',extra]).length,2);assert.ok(eligibleModifierIds([extra],'poison','sunny-pond').includes('sticky_frogs'));}const v=new ChaosVoting(true,()=>0,15,2);v.active=['sticky_frogs','mega_tongues','super_suckers'];v.open(0);assert.ok(v.choices.includes('sticky_frogs'));v.vote('host','sticky_frogs',v.ballotId,['host'],0);v.advance(15,['host']);assert.deepEqual(v.active,['mega_tongues','super_suckers','sticky_frogs']);assert.equal(STICKY.jumpCooldownTicks,12);});
test('2/8 frogs across all four arenas and targeted stacks remain finite and restore baseline',()=>{for(const a of arenaList)for(const n of[2,8])for(const extra of['gravity_flip','moon_frogs','tilt_a_frog','crumble_time','butterfeet','pogo_panic','mega_tongues','super_suckers','tiny_trouble','mega_frogs','windy_weather']as ModifierId[]){const s=fresh(['sticky_frogs',extra],a.id,n);for(let i=0;i<720;i++){s.frogs.forEach((_,j)=>s.setInput(j,{x:(i+j*11)%180<90?1:-1,y:i%160<80?-1:1,held:(i+j*7)%70<25}));s.step();for(const f of s.frogs)assert.ok(Number.isFinite(f.body.getPosition().x+f.body.getPosition().y+f.body.getLinearVelocity().length())&&f.body.getLinearVelocity().length()<100);}applyChaos(s,[]);assert.deepEqual(s.tuning,defaults);assert.equal(s.stickyFrogs.capture(),undefined);}});
test('Authored crumble platform deactivation releases a sticky underside without restoring hidden geometry',()=>{for(const arena of arenaList){const s=fresh(['sticky_frogs','crumble_time'],arena.id),state=s.arenaChaos.capture()!,p=state.platforms[0],f=s.frogs[0];s.frogs[1].body.setActive(false);const terrain=[];for(let b=s.world.getBodyList();b;b=b.getNext())if((b.getUserData()as any)?.chaosPlatform)terrain.push(b);const body=terrain.find(b=>Math.abs(b.getPosition().x-p.x!)<.001&&Math.abs(b.getPosition().y-p.y!)<.001)!;let under:any;for(let fixture=body.getFixtureList();fixture;fixture=fixture.getNext())s.world.rayCast(Vec2(p.x!,p.y!+p.solid.h+2),Vec2(p.x!,p.y!),(fix,point,n,fraction)=>{if(fix.getBody()!==body)return -1;under={point,n};return fraction;});assert.ok(under);f.body.setTransform(Vec2(under.point.x+under.n.x*(s.tuning.frogRadius-.01),under.point.y+under.n.y*(s.tuning.frogRadius-.01)),0);s.world.step(0);s.world.step(0);s.stickyFrogs.before();assert.ok(s.stickyFrogs.support(f)?.body===body);p.stage='cracking';p.clock=1;s.arenaChaos.restore(state);s.arenaChaos.before();s.stickyFrogs.before();assert.equal(body.isActive(),false);assert.equal(s.stickyFrogs.support(f),undefined);assert.equal(s.arenaChaos.capture()!.platforms[0].stage,'absent');}});
test('Moving support carries a stationary sticky frog using actual point velocity; tangential momentum survives jump',()=>{const s=fresh(),{b,f}=face(s);b.setType('kinematic');b.setLinearVelocity(Vec2(1,0));for(let i=0;i<90;i++)s.step();assert.ok(s.stickyFrogs.support(f)?.body===b);assert.ok(Math.abs(f.body.getPosition().x-b.getPosition().x)<.15);f.body.setLinearVelocity(Vec2(3,0));s.launch(f,0,0);assert.equal(f.body.getLinearVelocity().x,3);assert.equal(f.body.getLinearVelocity().y,-defaults.jumpImpulse);});
test('Artwork rotates feet onto each face; identities/labels and approved gravity-only flip remain separate',()=>{const source=readFileSync(new URL('../src/presentation/courtyard.ts',import.meta.url),'utf8'),method=source.slice(source.indexOf(' frog(g:'),source.lastIndexOf('\n}')),js=transpileModule('class Art {reactions=[0];appearances=[{}];'+method+'}',{compilerOptions:{target:ScriptTarget.ES2022}}).outputText;const make=new Function('defaults','S','INK','poisonRole','appearanceLayers','POISON_ACCENTS','paintFrogCore','hatAnchor','paintHat',js+';return new Art();'),noop=()=>{},art=make(defaults,32,0,()=>({tagging:false,transforming:false,spotted:false}),()=>({skin:{color:1},appearance:{},showPattern:false,hat:'none'}),[0],noop,()=>0,noop);for(const n of[{x:0,y:-1},{x:1,y:0},{x:0,y:1},{x:-1,y:0}]){const calls:any[]=[];const g=new Proxy({}as any,{get:(_o,name)=>(...args:any[])=>{calls.push([name,...args]);return g;}});art.frog(g,100,100,{stickyNormal:n,radius:.45,facing:1,grounded:true,charge:0,vy:0,vx:0},0,undefined,true,false,0);assert.equal(calls.find(c=>c[0]==='rotateCanvas')?.[1],Math.atan2(n.x,-n.y));assert.equal(calls.at(-1)[0],'restore');}assert.ok(source.includes("label.setBackgroundColor('transparent')"));assert.ok(source.includes('else if(f.gravityDirection===-1)g.scaleCanvas(1,-1)'));});
test('Approved 19-modifier, arena, controls/viewport, mode, sound and networking source stays exactly recoverable',()=>{const m=JSON.parse(readFileSync(new URL('../docs/sticky-preservation.json',import.meta.url),'utf8')),h=(s:string|Buffer)=>createHash('sha256').update(s).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(h(stickyPreservedSource(p)),r.beforeSha256,p);assert.equal(h(departurePreservedSource(p)),r.afterSha256,p);}for(const[p,hash]of Object.entries(m.protected))assert.equal(h(departurePreservedSource(p)),hash,p);for(const[p,hash]of Object.entries(m.newFiles))assert.equal(h(departurePreservedSource(p)),hash,p);for(const p of['src/main.ts','src/input/touch.ts','src/network/predictor.ts','server/outbreak-room.ts','src/chaos/frog-chaos.ts','src/chaos/arena-chaos.ts','src/simulation/surfaces.ts','src/simulation/config.ts','src/presentation/audio.ts'])assert.ok(m.protected[p],p);});
